'use client';

/* Motion leaves, isolated per Section 2 so server components stay static.
   Springs only, no linear easing (Section 4). */

import { motion, useReducedMotion, type Variants } from 'framer-motion';
import { useEffect, useState, type ReactNode } from 'react';

const SPRING = { type: 'spring' as const, stiffness: 100, damping: 20 };

export const stagger: Variants = {
  hidden: {},
  show: { transition: { staggerChildren: 0.07, delayChildren: 0.05 } },
};

/* Content is never hidden by motion. The reveal moves the element, it does not
   gate its visibility, so a failed script or an observer that never fires can
   only cost the animation, never the content. */
export const riseIn: Variants = {
  hidden: { opacity: 1, y: 16 },
  show: { opacity: 1, y: 0, transition: SPRING },
};

export function Stagger({
  children,
  className,
  amount = 0.15,
}: {
  children: ReactNode;
  className?: string;
  amount?: number;
}) {
  const reduce = useReducedMotion();

  /* Safety net: children start at opacity 0, so if IntersectionObserver never
     fires (hidden tab, prerender, observer unsupported) the content would stay
     invisible for good. Force the shown state after a beat. */
  const [forced, setForced] = useState(false);
  useEffect(() => {
    const t = setTimeout(() => setForced(true), 1200);
    return () => clearTimeout(t);
  }, []);

  if (reduce) return <div className={className}>{children}</div>;

  // Once forced, drive with `animate` alone. Leaving whileInView attached
  // alongside it stops the variant propagating to the children.
  if (forced) {
    return (
      <motion.div className={className} variants={stagger} initial="hidden" animate="show">
        {children}
      </motion.div>
    );
  }

  return (
    <motion.div
      className={className}
      variants={stagger}
      initial="hidden"
      whileInView="show"
      viewport={{ once: true, amount }}
    >
      {children}
    </motion.div>
  );
}

export function Rise({ children, className }: { children: ReactNode; className?: string }) {
  const reduce = useReducedMotion();
  if (reduce) return <div className={className}>{children}</div>;
  return (
    <motion.div className={className} variants={riseIn}>
      {children}
    </motion.div>
  );
}

/* Perpetual micro-interaction: a status dot that breathes (Section 4). */
export function LiveDot({ className = '' }: { className?: string }) {
  const reduce = useReducedMotion();
  return (
    <motion.span
      className={`inline-block size-1.5 rounded-full bg-accent ${className}`}
      animate={reduce ? undefined : { opacity: [1, 0.45, 1], scale: [1, 0.82, 1] }}
      transition={reduce ? undefined : { duration: 2.6, repeat: Infinity, ease: 'easeInOut' }}
    />
  );
}
